record Lens<S, A>(Function<S, A> get, BiFunction<S, A, S> set) {
    <B> Lens<S, B> andThen(Lens<A, B> inner) {
        return new Lens<>(s -> inner.get().apply(get.apply(s)),
                          (s, b) -> set.apply(s, inner.set().apply(get.apply(s), b)));
    }
}
